// ICP v2: two gates, then weighted points. Every score carries its reasoning.
const now = Date.now();
const out = [];
for (const it of $input.all()) {
  const c = it.json;
  const countries = c.countries || [];
  const tech = c.tech_hits || [];
  let open = 'no';
  if (c.open_worldwide || c.includes_nigeria) open = 'yes';
  else if (c.includes_africa || countries.length >= 3) open = 'maybe';
  const gate = open !== 'no';
  const reasons = [];
  let score = 0;
  if (!gate) {
    reasons.push(`Gated out: only hires in ${countries.slice(0, 3).join(', ') || 'one country'}.`);
  } else {
    reasons.push(`Gates passed: hiring (${c.post_count} GTM post${c.post_count > 1 ? 's' : ''}); remote ${open === 'yes' ? 'confirmed (worldwide or includes Nigeria)' : 'possible (hires in Africa or 3+ countries)'}.`);
    if (c.role_fit) { score += 30; reasons.push('Role fit +30: a role at junior-mid level.'); }
    else reasons.push('Role fit 0: only senior/leadership titles.');
    if (tech.length) { score += 20; reasons.push(`Tech +20: posts mention ${tech.join(', ')}.`); }
    else reasons.push('Tech 0: no target tools mentioned.');
    if (open === 'yes') { score += 15; reasons.push('Remote confirmed +15.'); }
    else reasons.push('Remote confirmed 0: open to some regions, Nigeria not confirmed.');
    const age = Math.floor((now - Date.parse(c.latest_post_at)) / 86400000);
    if (age <= 7) { score += 15; reasons.push(`Freshness +15: newest post ${age} days old.`); }
    else reasons.push(`Freshness 0: newest post ${age} days old.`);
    reasons.push('Reachable and Company size: unverified (0).');
  }
  reasons.push(`Titles: ${(c.hiring_titles || []).slice(0, 3).join('; ')}.`);
  out.push({ json: {
    company_key: c.company_key,
    company_name: c.company_name,
    domain: c.domain,
    domain_confidence: c.domain_confidence,
    gate_passed: gate,
    open_to_lagos: open,
    icp_score: score,
    icp_reasoning: reasons.join(' '),
    scored_at: new Date().toISOString()
  }});
}
return out;

// Only companies that passed the gates, scored 50 or more, and have a HIGH-confidence domain (the Salesforce key).
// 'review' domains stay in Supabase until checked by hand.
return $input.all().filter(i => i.json.gate_passed && i.json.icp_score >= 50 && i.json.domain && i.json.domain_confidence === 'high');

// Group qualified companies into batches of 200 for the Composite API.
const today = new Date().toISOString().slice(0, 10);
const all = $input.all().map(i => i.json);
const out = [];
for (let s = 0; s < all.length; s += 200) {
  const chunk = all.slice(s, s + 200);
  out.push({ json: {
    keys: chunk.map(c => c.company_key),
    body: {
      allOrNone: false,
      records: chunk.map(c => ({
        attributes: { type: 'Account' },
        Name: c.company_name,
        Domain__c: c.domain,
        ICP_Score__c: c.icp_score,
        ICP_Score_Reasoning__c: String(c.icp_reasoning).slice(0, 5000),
        Enrichment_Source__c: 'Web',
        Data_Last_Verified__c: today
      }))
    }
  }});
}
return out;

// Match each Salesforce result back to its company (results come back in the same order as sent).
const batches = $('Build Salesforce batches').all();
const out = [];
for (const item of $input.all()) {
  const idx = item.pairedItem?.item ?? 0;
  const keys = batches[idx].json.keys;
  const sent = batches[idx].json.body.records;
  let results = [];
  try { results = JSON.parse(item.json.data || '[]'); } catch (e) { results = []; }
  results.forEach((r, k) => {
    out.push({ json: {
      company_key: keys[k],
      ok: !!r.success,
      sf_account_id: r.id || null,
      created: !!r.created,
      error: r.success ? null : JSON.stringify(r.errors || []),
      record: sent[k]
    }});
  });
}
return out;

// One row for the runs logbook.
const results = $input.all();
return [{ json: {
  started_at: $('Score with ICP v2').first().json.scored_at,
  finished_at: new Date().toISOString(),
  sourced: $('Get companies to score').all().length,
  new_companies: $('Score with ICP v2').all().filter(i => i.json.gate_passed).length,
  qualified: $('Keep qualified (50+)').all().length,
  upserted: results.filter(i => i.json.ok).length,
  errors: results.filter(i => !i.json.ok).length
}}];
